Requires `@videojs/react@10.2.0`, which is installed with this item. The native media element below handles browser-supported sources; [install a playback adapter](https://videojs.org/docs/framework/react/concepts/media-sources/) for HLS, DASH, embeds, or another engine.

```tsx
import { Audio, AudioPlayer } from '@videojs/react/audio';

import { AudioSkin } from '@/components/videojs/audio/skin';

export function Player({ src }: { src: string }) {
  return (
    <AudioPlayer>
      <AudioSkin className="aspect-video w-full">
        <Audio src={src} />
      </AudioSkin>
    </AudioPlayer>
  );
}
```

